create temporary view homepage_metrics_${grass_region_without_quote} as
select
    platform
    ,item_click_level
    ,dd_click_level
    ,major_app_version
    ,app_version
    ,nvl(module, '__ALL__') as module
    ,nvl(object, '__ALL__') as object
    ,sum(stay_duration) as stay_duration
    ,count(distinct if(view_cnt>0, user_id, null)) as view_uu
    ,sum(imp_cnt) as imp_cnt
    ,sum(organic_imp_cnt) as organic_imp_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,count(distinct if(imp_cnt>0, user_id, null)) as imp_uu
    ,sum(click_cnt) as click_cnt
    ,sum(organic_click_cnt) as organic_click_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
    ,count(distinct if(click_cnt>0, user_id, null)) as click_uu
    ,sum(omni_imp_cnt) as omni_imp_cnt
    ,sum(organic_omni_imp_cnt) as organic_omni_imp_cnt
    ,sum(ads_omni_imp_cnt) as ads_omni_imp_cnt
    ,sum(omni_click_cnt) as omni_click_cnt
    ,sum(organic_omni_click_cnt) as organic_omni_click_cnt
    ,sum(ads_omni_click_cnt) as ads_omni_click_cnt
    ,sum(ppv_cnt) as ppv_cnt
    ,sum(organic_ppv_cnt) as organic_ppv_cnt
    ,sum(ads_ppv_cnt) as ads_ppv_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(organic_order_cnt) as organic_order_cnt
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(gmv) as gmv
    ,sum(organic_gmv) as organic_gmv
    ,sum(ads_gmv) as ads_gmv
from version_roll_up_data_${grass_region_without_quote}
group by platform, item_click_level, dd_click_level, major_app_version, app_version, module, object
-- roll up with module, object
grouping sets(
    (platform, item_click_level, dd_click_level, major_app_version, app_version)
    ,(platform, item_click_level, dd_click_level, major_app_version, app_version, module)
    ,(platform, item_click_level, dd_click_level, major_app_version, app_version, module, object)
)

