create temporary view platform_order_agg_${grass_region_without_quote} as
select
    coalesce(platform, '') as platform
    ,coalesce(app_version, '') as app_version
    ,coalesce(regexp_extract(app_version, '(.+)(\\.)(.+)', 1), '') as major_app_version
    ,sum(operation_cnt) as platform_order_cnt
    ,sum(place_order_gmv) as platform_gmv
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation = 'order'
group by platform, app_version

--sql_divide_splitter--
create temporary view platform_order_cube_${grass_region_without_quote} as
select
    coalesce(platform, '__ALL__') as platform
    ,'__ALL__' as item_click_level
    ,'__ALL__' as dd_click_level
    ,coalesce(major_app_version, '__ALL__') as major_app_version
    ,coalesce(app_version, '__ALL__') as app_version
    ,'__ALL__' as module
    ,'__ALL__' as object
    ,sum(platform_order_cnt) as platform_order_cnt
    ,sum(platform_gmv) as platform_gmv
from platform_order_agg_${grass_region_without_quote}
group by grouping sets(
    ()
    ,(major_app_version)
    ,(major_app_version, app_version)
    ,(platform)
    ,(platform, major_app_version)
    ,(platform, major_app_version, app_version)
)

