insert overwrite table ${schema}.dws_sr_data_warehouse_homepage_user_attribute_level_1d
partition(grass_region=${grass_region}, local_date=${local_date})
select
    coalesce(t1.platform, t2.platform) as platform
    ,coalesce(t1.item_click_level, t2.item_click_level) as item_click_level
    ,coalesce(t1.dd_click_level, t2.dd_click_level) as dd_click_level
    ,coalesce(t1.major_app_version, t2.major_app_version) as major_app_version
    ,coalesce(t1.app_version, t2.app_version) as app_version
    ,coalesce(t1.module, t2.module) as module
    ,coalesce(t1.object, t2.object) as object
    ,coalesce(t1.stay_duration, 0) as stay_time
    ,coalesce(t1.view_uu, 0) as view_uu
    ,coalesce(t1.imp_cnt, 0) as imp_cnt
    ,coalesce(t1.organic_imp_cnt, 0) as organic_imp_cnt
    ,coalesce(t1.ads_imp_cnt, 0) as ads_imp_cnt
    ,coalesce(t1.imp_uu, 0) as imp_uu
    ,coalesce(t1.click_cnt, 0) as click_cnt
    ,coalesce(t1.organic_click_cnt, 0) as organic_click_cnt
    ,coalesce(t1.ads_click_cnt, 0) as ads_click_cnt
    ,coalesce(t1.click_uu, 0) as click_uu
    ,coalesce(t1.omni_imp_cnt, 0) as omni_imp_cnt
    ,coalesce(t1.organic_omni_imp_cnt, 0) as organic_omni_imp_cnt
    ,coalesce(t1.ads_omni_imp_cnt, 0) as ads_omni_imp_cnt
    ,coalesce(t1.omni_click_cnt, 0) as omni_click_cnt
    ,coalesce(t1.organic_omni_click_cnt, 0) as organic_omni_click_cnt
    ,coalesce(t1.ads_omni_click_cnt, 0) as ads_omni_click_cnt
    ,coalesce(t1.ppv_cnt, 0) as ppv_cnt
    ,coalesce(t1.organic_ppv_cnt, 0) as organic_ppv_cnt
    ,coalesce(t1.ads_ppv_cnt, 0) as ads_ppv_cnt
    ,coalesce(t1.order_cnt, 0) as order_cnt
    ,coalesce(t1.organic_order_cnt, 0) as organic_order_cnt
    ,coalesce(t1.ads_order_cnt, 0) as ads_order_cnt
    ,coalesce(t1.gmv, 0) as gmv
    ,coalesce(t1.organic_gmv, 0) as organic_gmv
    ,coalesce(t1.ads_gmv, 0) as ads_gmv
    ,coalesce(t2.platform_order_cnt, 0) as platform_order_cnt
    ,coalesce(t2.platform_gmv, 0) as platform_gmv
from homepage_metrics_${grass_region_without_quote} as t1
full outer join platform_order_cube_${grass_region_without_quote} as t2
on t1.platform = t2.platform
    and t1.item_click_level = t2.item_click_level
    and t1.dd_click_level = t2.dd_click_level
    and t1.major_app_version = t2.major_app_version
    and t1.app_version = t2.app_version
    and t1.module = t2.module
    and t1.object = t2.object
